// Answers retired URLs with 410 Gone so search engines drop them quickly.
// The list is generated by scripts/build_redirects.py from data/url_inventory.csv.
import gone from './gone.json';

const GONE = new Set(gone);
const PAGE = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Page removed | Joe Unhammer</title><style>body{font:18px/1.6 Georgia,serif;max-width:40rem;margin:15vh auto;padding:0 1rem;color:#17202e;background:#f3f5f7}a{color:#1f4e6b}</style></head><body><h1>This page was removed</h1><p>It no longer fits what this site covers. Try <a href="/blog/">the writing archive</a> or <a href="/">the home page</a>.</p></body></html>`;

export async function onRequest(context) {
  const { pathname } = new URL(context.request.url);
  const path = pathname.endsWith('/') ? pathname : pathname + '/';
  if (GONE.has(path)) {
    return new Response(PAGE, { status: 410, headers: { 'content-type': 'text/html; charset=utf-8' } });
  }
  return context.next();
}
